// The browse-scale 3.2 duty: the facets route (serving order verbatim,
// honest empty, the visibility conjunct — an invisible library serves
// nothing) and the additive facet filters on the collection listings
// (id-set resolution + in-Go intersection, composition with
// library/folders/sort/status, unknown value → 200 empty) — asserted over
// the real router wiring and a real store, the browse index injected through
// the Deps closures exactly as cmd wires them.

// facetRecorder is the Deps.FacetIDs stub: it records every invocation's
// filter triple ("genre|kind|status") and serves the id sets its tables
// carry for that record — a missing record is the unknown-value law (empty
// sets, never an error), exactly what the cmd-side resolution yields for a
// value no document carries.
type facetRecorder struct {
	calls  []string
	series map[string]map[string]bool
	items  map[string]map[string]bool
	err    error // when set, every resolution fails (the 500 path)
}

func (fr *facetRecorder) resolve(_ context.Context, _ int64, genre, kind, status string) (map[string]bool, map[string]bool, error) {
	key := genre + "|" + kind + "|" + status
	fr.calls = append(fr.calls, key)
	if fr.err != nil {
		return nil, nil, fr.err
	}
	return fr.series[key], fr.items[key], nil
}

// lastCall is the one filter triple the most recent listing request resolved.
func (fr *facetRecorder) lastCall(t *testing.T) string {
	t.Helper()
	if len(fr.calls) == 0 {
		t.Fatalf("FacetIDs never invoked")
	}
	return fr.calls[len(fr.calls)-1]
}

// newFacetsAPI builds the router over a fresh serial library with the facet
// closures injected (nil = the not-wired floor), the newRecsAPI posture.
func newFacetsAPI(t *testing.T, lf func(int64) ([]string, [][]string, [][]int), fid func(context.Context, int64, string, string, string) (map[string]bool, map[string]bool, error)) (http.Handler, *store.Store, int64) {
	t.Helper()
	st := openAPIStore(t)
	h := New(Deps{
		AdminToken: adminToken,
		Store:      st,
		ModulePresentation: func(_ context.Context, _ string, _ int64) (ModulePresentation, error) {
			return ModulePresentation{SourceChain: []titleSourceBinding{{ID: recsMetaNS, Enabled: true}}}, nil
		},
		LibraryFacets: lf,
		FacetIDs:      fid,
	})
	libID, err := st.CreateLibrary(context.Background(), "serial", "/media/facets", "Facets")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	return h, st, libID
}

// facetSeedItem puts one item row with an explicit lifecycle status and
// returns the stored row (seedRecsItem's posture, plus the status).
func facetSeedItem(t *testing.T, st *store.Store, libraryID int64, id, relPath, status string, doc map[string]any) store.Item {
	t.Helper()
	if err := st.PutItem(context.Background(), store.Item{
		ID: id, ModuleID: "serial", LibraryID: libraryID, FileID: id,
		RelativePath: relPath, MediaType: "serial", Status: status,
		Document: recsDoc(t, doc), SchemaVersion: 1,
	}); err != nil {
		t.Fatalf("PutItem %s: %v", id, err)
	}
	got, err := st.GetItem(context.Background(), id, access.System())
	if err != nil {
		t.Fatalf("GetItem %s: %v", id, err)
	}
	return got
}

// TestFacetsRoute covers GET /libraries/{id}/facets: the aggregates served
// verbatim in the index's serving order, the honest empty list, the
// canonical errors, and the visibility conjunct — a library outside the
// caller's visible set serves 404 like every other denied library-scoped
// view (no counts, no keys, no existence leak).
func TestFacetsRoute(t *testing.T) {
	serve := func(keys []string, values [][]string, counts [][]int) (http.Handler, *store.Store, int64) {
		return newFacetsAPI(t,
			func(int64) ([]string, [][]string, [][]int) { return keys, values, counts },
			nil,
		)
	}

	t.Run("serves_index_order_verbatim", func(t *testing.T) {
		h, _, lib := serve(
			[]string{"genres", "kind"},
			[][]string{{"Drama", "Adventure"}, {"movie"}},
			[][]int{{3, 1}, {4}},
		)
		resp := doRequest(t, h, http.MethodGet, "/api/v1/libraries/"+itoa64(lib)+"/facets", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		var got facetsResponse
		if err := json.NewDecoder(resp.Body).Decode(&got); err != nil {
			t.Fatalf("decode facetsResponse: %v", err)
		}
		if len(got.Facets) != 2 {
			t.Fatalf("served %d facets, want 2", len(got.Facets))
		}
		if got.Facets[0].Key != "genres" || got.Facets[1].Key != "kind" {
			t.Fatalf("served keys %q/%q, want genres/kind in index order", got.Facets[0].Key, got.Facets[1].Key)
		}
		want := []facetValueDTO{{"Drama", 3}, {"Adventure", 1}}
		for i, wv := range want {
			if got.Facets[0].Values[i] != wv {
				t.Fatalf("genres values %v, want %v (count desc, value asc)", got.Facets[0].Values, want)
			}
		}
		if got.Facets[1].Values[0] != (facetValueDTO{"movie", 4}) {
			t.Fatalf("kind values %v, want [{movie 4}]", got.Facets[1].Values)
		}
	})

	t.Run("no_aggregates_serve_empty_list_not_null", func(t *testing.T) {
		h, _, lib := serve(nil, nil, nil)
		resp := doRequest(t, h, http.MethodGet, "/api/v1/libraries/"+itoa64(lib)+"/facets", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		body, err := io.ReadAll(resp.Body)
		if err != nil {
			t.Fatalf("read body: %v", err)
		}
		if got := strings.TrimSpace(string(body)); got != `{"facets":[]}` {
			t.Fatalf("body = %s, want {\"facets\":[]}", got)
		}
	})

	t.Run("unknown_library_is_404", func(t *testing.T) {
		h, _, _ := serve(nil, nil, nil)
		resp := doRequest(t, h, http.MethodGet, "/api/v1/libraries/999/facets", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNotFound {
			t.Fatalf("status = %d, want 404", resp.StatusCode)
		}
	})

	t.Run("non_integer_id_is_400", func(t *testing.T) {
		h, _, _ := serve(nil, nil, nil)
		resp := doRequest(t, h, http.MethodGet, "/api/v1/libraries/abc/facets", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want 400", resp.StatusCode)
		}
	})

	t.Run("invisible_library_serves_nothing", func(t *testing.T) {
		_, st, lib1 := serve(
			[]string{"genres"},
			[][]string{{"Drama"}},
			[][]int{{3}},
		)
		lib2, err := st.CreateLibrary(context.Background(), "serial", "/media/hidden", "Hidden")
		if err != nil {
			t.Fatalf("CreateLibrary lib2: %v", err)
		}
		// A viewer granted ONLY lib2: lib1's facets are unknown to it —
		// 404, the denied library-scoped view (no leak of facet existence).
		scoped := func() http.Handler {
			h := &app{deps: Deps{
				AdminToken: adminToken,
				Store:      st,
				LibraryFacets: func(int64) ([]string, [][]string, [][]int) {
					return []string{"genres"}, [][]string{{"Drama"}}, [][]int{{3}}
				},
			}}
			r := chi.NewRouter()
			r.Use(principalInjector(RoleClient), principalViewerInjector(access.User(42, []int64{lib2}, nil)))
			r.Route("/api/v1", func(r chi.Router) { mountV1Routes(r, h) })
			return r
		}()
		resp := doRequest(t, scoped, http.MethodGet, "/api/v1/libraries/"+itoa64(lib1)+"/facets", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNotFound {
			t.Fatalf("denied library status = %d, want 404", resp.StatusCode)
		}
		// The granted half of the conjunct: lib2 serves 200 to the SAME viewer.
		resp2 := doRequest(t, scoped, http.MethodGet, "/api/v1/libraries/"+itoa64(lib2)+"/facets", "", adminToken)
		defer resp2.Body.Close()
		if resp2.StatusCode != http.StatusOK {
			t.Fatalf("granted library status = %d, want 200", resp2.StatusCode)
		}
	})

	t.Run("nil_closure_is_503", func(t *testing.T) {
		h, _, lib := newFacetsAPI(t, nil, nil)
		resp := doRequest(t, h, http.MethodGet, "/api/v1/libraries/"+itoa64(lib)+"/facets", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusServiceUnavailable {
			t.Fatalf("status = %d, want 503", resp.StatusCode)
		}
	})
}

// TestFacetFilterParams covers the additive facet filters on the collection
// listings: id-set resolution + in-Go intersection, composition with
// library/folders/sort and the pinned lifecycle status, the unknown-value
// 200-empty law, the filter-then-window page cut on the path branch, and
// the visibility conjunct. The seeded docs carry no metadata namespace, so
// every score floors to 0 and the scored default serves display-name
// ascending — the deterministic backdrop the composition assertions need.
func TestFacetFilterParams(t *testing.T) {
	rec := &facetRecorder{
		series: map[string]map[string]bool{},
		items:  map[string]map[string]bool{},
	}
	h, st, lib := newFacetsAPI(t, nil, rec.resolve)

	// Three series, alphabetical paths: a/b carry the Adventure genre, c
	// carries nothing.
	serA := seedRecsSeries(t, st, lib, "a-adventure", recsSeriesDoc("AAdventure"))
	serB := seedRecsSeries(t, st, lib, "b-adventure", recsSeriesDoc("BAdventure"))
	seedRecsSeries(t, st, lib, "c-plain", recsSeriesDoc("CPlain"))
	// Three items: two episodes under the a/b series, one standalone film-like
	// row; only itm_1 is lifecycle-ready.
	itm1 := facetSeedItem(t, st, lib, "itm_1", "a-adventure/e1.mkv", "ready", recsEpisodeDoc("a-adventure", ""))
	itm2 := facetSeedItem(t, st, lib, "itm_2", "b-adventure/e2.mkv", "", recsEpisodeDoc("b-adventure", ""))
	itm3 := facetSeedItem(t, st, lib, "itm_3", "c-plain.mkv", "", map[string]any{"parsed": map[string]any{"dir_name_raw": "CPlain"}})

	// The resolved id sets (what the cmd-side facet corpus would resolve).
	rec.series["Adventure||"] = map[string]bool{serA.ID: true, serB.ID: true}
	rec.series["Adventure|movie|Ended"] = map[string]bool{serA.ID: true}
	rec.items["Adventure||"] = map[string]bool{itm1.ID: true, itm2.ID: true}
	// The filter-then-window discriminator: the set EXCLUDES the first path
	// row, so page one of the filtered path order starts at itm_2 (a
	// window-then-filter read would serve itm_1's page as empty).
	rec.items["Exclusive||"] = map[string]bool{itm2.ID: true, itm3.ID: true}

	t.Run("genre_narrows_series", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series?library="+itoa64(lib)+"&genre=Adventure", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		rows := decodeSeriesList(t, resp)
		wantIDs(t, servedIDs(rows, func(d seriesDTO) string { return d.ID }), serA.ID, serB.ID)
	})

	t.Run("composes_with_sort_path", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series?library="+itoa64(lib)+"&genre=Adventure&sort=path", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		rows := decodeSeriesList(t, resp)
		// QuerySeries' relative_path order, preserved by the intersection.
		wantIDs(t, servedIDs(rows, func(d seriesDTO) string { return d.ID }), serA.ID, serB.ID)
		for _, d := range rows {
			if d.RecScore != 0 {
				t.Fatalf("sort=path computed scores (%v on %s)", d.RecScore, d.ID)
			}
		}
	})

	t.Run("kind_and_status_conjunct_and_resolved_verbatim", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series?library="+itoa64(lib)+"&genre=Adventure&kind=movie&status=Ended", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		rows := decodeSeriesList(t, resp)
		wantIDs(t, servedIDs(rows, func(d seriesDTO) string { return d.ID }), serA.ID)
		if got := rec.lastCall(t); got != "Adventure|movie|Ended" {
			t.Fatalf("FacetIDs resolved %q, want %q", got, "Adventure|movie|Ended")
		}
	})

	t.Run("unknown_value_is_200_empty", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series?library="+itoa64(lib)+"&genre=Nope", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		if rows := decodeSeriesList(t, resp); len(rows) != 0 {
			t.Fatalf("served %d rows, want the empty list", len(rows))
		}
	})

	t.Run("items_genre_composes_with_sort_path", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items?library="+itoa64(lib)+"&genre=Adventure&sort=path", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		lr := decodeItems(t, resp)
		wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }), itm1.ID, itm2.ID)
		// The item listing passes NO facet status: the /items `status` name
		// is pinned to the lifecycle filter.
		if got := rec.lastCall(t); got != "Adventure||" {
			t.Fatalf("FacetIDs resolved %q, want %q (no facet status on /items)", got, "Adventure||")
		}
	})

	t.Run("items_status_stays_lifecycle_and_composes", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items?library="+itoa64(lib)+"&status=ready&genre=Adventure", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		lr := decodeItems(t, resp)
		// The lifecycle filter (status=ready) AND the facet conjunct apply
		// together: only the ready episode survives.
		wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }), itm1.ID)
		if got := rec.lastCall(t); got != "Adventure||" {
			t.Fatalf("FacetIDs resolved %q, want %q", got, "Adventure||")
		}
	})

	t.Run("filtered_path_branch_windows_after_the_filter", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items?library="+itoa64(lib)+"&sort=path&genre=Exclusive&limit=1&offset=0", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		lr := decodeItems(t, resp)
		// Filter-then-window: page one of the FILTERED path order (a
		// window-then-filter read would serve the empty page — the SQL
		// window's first row carries no Exclusive value).
		wantIDs(t, servedIDs(lr.Items, func(d itemDTO) string { return d.ID }), itm2.ID)
	})

	t.Run("invisible_library_contributes_nothing", func(t *testing.T) {
		// A viewer granted NOTHING: the store's visibility conjunct empties
		// the row set before any filter runs — 200 empty, no leak.
		scoped := func() http.Handler {
			a := &app{deps: Deps{
				AdminToken: adminToken,
				Store:      st,
				FacetIDs:   rec.resolve,
			}}
			r := chi.NewRouter()
			r.Use(principalInjector(RoleClient), principalViewerInjector(access.User(43, nil, nil)))
			r.Route("/api/v1", func(r chi.Router) { mountV1Routes(r, a) })
			return r
		}()
		for _, path := range []string{
			"/api/v1/series?library=" + itoa64(lib) + "&genre=Adventure",
			"/api/v1/items?library=" + itoa64(lib) + "&genre=Adventure",
		} {
			resp := doRequest(t, scoped, http.MethodGet, path, "", adminToken)
			if resp.StatusCode != http.StatusOK {
				t.Fatalf("%s: status = %d, want 200", path, resp.StatusCode)
			}
			body, err := io.ReadAll(resp.Body)
			resp.Body.Close()
			if err != nil {
				t.Fatalf("%s: read body: %v", path, err)
			}
			if got := strings.TrimSpace(string(body)); got != `{"items":[]}` {
				t.Fatalf("%s: body = %s, want {\"items\":[]}", path, got)
			}
		}
	})

	t.Run("filters_with_nil_closure_are_503_unfiltered_serve", func(t *testing.T) {
		bare, _, bareLib := newFacetsAPI(t, nil, nil)
		// A filter with the resolution floor unwired is a 503 — a silently
		// ignored filter would serve a row set the client cannot reason
		// about (the parseSort strict-parse posture).
		for _, path := range []string{
			"/api/v1/series?library=" + itoa64(bareLib) + "&genre=Adventure",
			"/api/v1/items?library=" + itoa64(bareLib) + "&kind=movie",
		} {
			resp := doRequest(t, bare, http.MethodGet, path, "", adminToken)
			if resp.StatusCode != http.StatusServiceUnavailable {
				t.Fatalf("%s: status = %d, want 503", path, resp.StatusCode)
			}
			resp.Body.Close()
		}
		// Unfiltered listings keep serving with the closure nil (nil-safe).
		for _, path := range []string{
			"/api/v1/series?library=" + itoa64(bareLib),
			"/api/v1/items?library=" + itoa64(bareLib),
		} {
			resp := doRequest(t, bare, http.MethodGet, path, "", adminToken)
			if resp.StatusCode != http.StatusOK {
				t.Fatalf("%s: status = %d, want 200", path, resp.StatusCode)
			}
			resp.Body.Close()
		}
	})

	t.Run("closure_error_is_500", func(t *testing.T) {
		failing := &facetRecorder{err: context.DeadlineExceeded}
		fh, _, flib := newFacetsAPI(t, nil, failing.resolve)
		resp := doRequest(t, fh, http.MethodGet, "/api/v1/series?library="+itoa64(flib)+"&genre=Adventure", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusInternalServerError {
			t.Fatalf("status = %d, want 500", resp.StatusCode)
		}
	})
}
